// swiper.js & css
import {calcTop, throttle} from '@utils/index.js'

// 数据埋码
function GAEvent(params) {
    window.dataLayer.push({ "event_parameters": null });
    window.dataLayer.push({
        "event":"ga4Event",
        "event_name":"anniversary_page_user_clicks",
        "event_parameters":{
            "current_page": window.location.href, // current page url,
            "module": "directory",
            ...params
        }
    })
}

export function InitCollectionTabs() {
    let scrolling = false
    const tabSwiper = new Swiper(".collection-tabs-content", {
      slidesPerView: 'auto'
    });

    const allHeights = (function() {
        const allHeight = []
        let uls = $(".collection-hero .collection-title");
        Array.from(uls).forEach((v) => {
            const key = $(v).attr("data-anchor")
            allHeight.push({
                collection: [key],
                value: v.getBoundingClientRect().top + window.pageYOffset - 40
            })
        });
        return allHeight
    })()

    $(".collection-tabs .scroll-wrapper .collection-tab-item").click(function(e) {
        tabSwiper.slideTo($(this).index(), 300, false);
        const _this = $(this)

        const target_name = $(this).attr('data-anchor')
        let t_ = ".collection-hero .collection-title[data-anchor='"+ target_name +"']"

        scrolling = true
        $('html, body').animate({
            scrollTop: $(t_).offset().top - $(".collection-tabs").height() - 40
        }, 300, 'swing', function() {
            scrolling = false
            $(".collection-tabs .scroll-wrapper .collection-tab-item").removeClass("active")
            _this.addClass("active")
        });

        // 数据埋码
        GAEvent({
            position: $(this).attr('data-title'),
            status: window?.pageInfo?.customerInfo?.id ? 'logged_in' : 'tourist',
        })
    })

    function invertCollectionTab() {
            function didChangeViewport() {
                const doc = $(".collection-product-main")[0]
                const elements = Array.from(
                    doc.querySelectorAll(".collection-hero,.product-grid__list")
                );
                const isMobile = window.innerWidth < 1024;

                const slide = elements.find((element) => {
                    const MARGIN = isMobile ? 30.0 : 65.0;
                    const {
                        top,
                        bottom
                    } = element.getBoundingClientRect();
                    return top < MARGIN && bottom > MARGIN;
                });
                if (slide) {
                    const collection = slide.dataset.collection
                    $(`.collection-tabs .scroll-wrapper .collection-tab-item`).removeClass("active")
                    tabSwiper.slideTo($(`.collection-tabs .scroll-wrapper .collection-tab-item[data-anchor=${collection}]`).index(), 300, false);
                    $(`.collection-tabs .scroll-wrapper .collection-tab-item[data-anchor=${collection}]`).addClass("active")
                } else {return}
        }

        window.addEventListener("scroll", didChangeViewport, {
            passive: true
        });
        didChangeViewport();

        return function destroyinvertCollectionTab() {
            window.removeEventListener("scroll", didChangeViewport);
        };
        
    };
    setTimeout(() => invertCollectionTab(), 200)
}