// 视窗内拖拽移动
export class DragToMove {
  constructor({
      el, // 目标元素
      placement = 'left', // 目标位置，'left' - 靠左，'right' - 靠右
      offset = { // 偏移量
          x: 0,
          y: 0,
      },
      onClick, // 点击事件
      closable = false, // 是否可关闭
      closableEl, // 关闭按钮元素
      closedCallback, // 关闭回调
  }) {
      this.DOM = document.querySelector(el)

      this.placement = placement
      this.offset = offset
      this.onClick = onClick
      this.closable = closable
      this.closableEl = closableEl
      this.closedCallback = closedCallback

      this.isDragging = false // 是否正在拖拽
      this.isClick = false // 是否点击

      this.offsetX = 0
      this.offsetY = 0

      this.windowWidth = window.innerWidth

      // 事件绑定 this 指向，方便移除
      this.start = this.start.bind(this)
      this.move = this.move.bind(this)
      this.end = this.end.bind(this)
      this.resize = this.resize.bind(this)

      this.initPosition()
      this.initEvent()
  }
  resize() { 
      if (this.windowWidth !== window.innerWidth) {
          this.windowWidth = window.innerWidth

          if (this.resizeTimer) clearTimeout(this.resizeTimer)

          this.resizeTimer = setTimeout(() => {
              this.initPosition()
          }, 500)
      }
  }
  // 初始化位置
  initPosition() {
      if (this.placement === 'left') {
          this.setPosition(this.offset.x, this.offset.y)
      } else {
          const { offsetWidth, offsetHeight, } = this.DOM
          const { clientWidth, clientHeight, } = document.documentElement

          if (this.offset.y.includes('%')) {
              this.setPosition(
                  clientWidth - offsetWidth - (this.offset.x || 0),
                  (clientHeight - offsetHeight) * parseInt(this.offset.y) / 100
              )
          } else {
              this.setPosition(clientWidth - offsetWidth - this.offset.x, clientHeight - offsetHeight - this.offset.y)
          }
      }
  }
  // 初始化方法
  initEvent() {
      // 禁止 DOM 元素的 drag 事件干扰
      this.DOM.addEventListener('dragstart', (e) => e.preventDefault())

      // PC
      this.DOM.addEventListener("mousedown", this.start, {passive: true})

      // Mobile
      this.DOM.addEventListener("touchstart", this.start, {passive: true})

      // 监听 resize
      window.addEventListener('resize', this.resize, false)
  }
  // 移除事件
  removeEvent() {
      // PC
      this.DOM.removeEventListener("mousedown", this.start, {passive: true})

      // Mobile
      this.DOM.removeEventListener("touchstart", this.start, {passive: true})

      // 监听 resize
      window.removeEventListener('resize', this.resize, false)
  }
  // 拖拽开始
  start(e) {
      this.isDragging = true
      this.isClick = true

      // 监听 move 事件
      document.addEventListener("mousemove", this.move, false)
      document.addEventListener("mouseup", this.end, {passive: true})

      this.DOM.addEventListener("touchmove", this.move, false)
      this.DOM.addEventListener("touchend", this.end, {passive: true})

      const event = e.touches ? e.touches[0] : e

      this.offsetX = event.clientX - this.DOM.offsetLeft
      this.offsetY = event.clientY - this.DOM.offsetTop
  }
  // 移动
  move(e) {
      if (this.isDragging) {
          e.preventDefault()
          e.stopPropagation()

          this.isClick = false

          const event = e.touches ? e.touches[0] : e

          const x = event.clientX - this.offsetX
          const y = event.clientY - this.offsetY

          const { clientWidth, clientHeight, } = document.documentElement

          const X = this.range(x, 0, clientWidth - this.DOM.offsetWidth)
          const Y = this.range(y, 0, clientHeight - this.DOM.offsetHeight)

          this.setPosition(X, Y)
      }
  }
  // 拖拽结束
  end(e) {
      this.isDragging = false
      e.stopPropagation()

      // 移除 move 事件
      document.removeEventListener("mousemove", this.move, false)
      document.removeEventListener("mouseup", this.end, {passive: true})

      this.DOM.removeEventListener("touchmove", this.move, false)
      this.DOM.removeEventListener("touchend", this.end, {passive: true})

      if (this.isClick && this.onClick) {
          if (this.closable && this.closableEl) {

              // closableEl 可能是 id，也可能是 class
              const name =
                  (this.closableEl.includes('#') && e.target.id) ||
                  (this.closableEl.includes('.') && e.target.className)

              if (name === this.closableEl.slice(1)) {
                  this.DOM.style.display = 'none'
                  this.closedCallback && this.closedCallback(e)

                  // 移除事件
                  this.removeEvent()
                  return false
              }
          }

          this.isClick = false
          this.onClick()
      }
  }
  // 更新元素位置
  setPosition(x, y) {
      this.DOM.style.left = `${x}px`
      this.DOM.style.top = `${y}px`
      this.DOM.style.opacity = 1
  }
  // 判断边界
  range(loc, min, max) {
      if (loc > max) {
          return max
      }
      if (loc < min) {
          return min
      }
      return loc
  }
}


